  Captions: "الترجمة المرئية",
  "Captions changed while you had an unsaved draft. Your draft is kept here for comparison.":
    "تغيرت الترجمة المرئية بينما كانت لديك مسودة غير محفوظة. احتفظنا بمسودتك هنا للمقارنة.",
  "Captions changed while you were editing. Load the saved captions before applying another revision.":
    "تغيرت الترجمة المرئية أثناء تحريرك. حمل الترجمة المحفوظة قبل تطبيق مراجعة أخرى.",
