  "Card color": "لون البطاقة",
  "Card padding": "الحشو الداخلي للبطاقة",
  "Carry useful ideas into your own brief with your subject, message, and references. Check the result against your actual source material.":
    "انقل الأفكار المفيدة إلى موجزك بموضوعك ورسالتك ومراجعك. راجع النتيجة مقابل موادك الأصلية الفعلية.",
  Center: "وسط",
  "Challenge an assumption, then earn attention with a specific alternative.":
    "تحد افتراضا، ثم اكسب الانتباه ببديل محدد.",
  "Change one creative variable at a time.":
    "غير متغيرا إبداعيا واحدا في كل مرة.",
  "Change or withdraw": "التغيير أو السحب",
  "Change the filters or run custom research. REELassati will show fewer results rather than fill the feed with stale, paid, generic, or unverified content.":
    "غير المرشحات أو نفذ بحثا مخصصا. يعرض REELassati نتائج أقل بدلا من ملء الخلاصة بمحتوى قديم أو مدفوع أو عام أو غير موثق.",
