    "تظهر التغييرات على خطك الزمني عند اكتمالها. يمكنك مواصلة تحريرها يدويا.",
  "Changes are saved as an undoable revision.":
    "تحفظ التغييرات كمراجعة يمكن التراجع عنها.",
  "Changes need attention": "التغييرات تحتاج إلى مراجعة",
