  Open: "فتح",
  "Open Adjust": "فتح الضبط",
  "Open Graphics → Motion kits for a brand reveal, speaker introduction, chapter, quote, statistic or closing card. Edit the text, accent and duration; the brand reveal can use a logo from Library. Add at the playhead, then refine the grouped layers on the timeline. Undo removes the whole insertion. These native templates use no AI credits.":
    "افتح الرسومات ← حزم الحركة لكشف علامة أو تقديم متحدث أو فصل أو اقتباس أو إحصائية أو بطاقة ختامية. عدل النص والإبراز والمدة؛ يمكن لكشف العلامة استخدام شعار من المكتبة. أضف عند رأس التشغيل ثم حسن الطبقات المجمعة على الخط الزمني. يزيل التراجع الإدراج كاملا. لا تستخدم هذه القوالب الأصلية رصيد الذكاء الاصطناعي.",
  "Open Library": "فتح المكتبة",
  "Open Prompt Director": "فتح موجه التعليمات",
  "Open Publisher": "فتح أداة النشر",
  "Open Stripe account setup": "فتح إعداد حساب Stripe",
  "Open Studio": "فتح الاستوديو",
  "Open a preset to read its direction and editable prompt. A preset supplies structure; your subject and source files make the result specific.":
    "افتح إعدادا جاهزا لقراءة توجيهه وموجهه القابل للتحرير. يوفر الإعداد بنية؛ يجعل موضوعك وملفاتك الأصلية النتيجة محددة.",
  "Open a publication in Publisher to change its draft or schedule. A calendar event plans work; it does not publish a post. Check the displayed workspace timezone.":
    "افتح منشورا في أداة النشر لتغيير مسودته أو جدولته. يخطط حدث التقويم للعمل ولا ينشر منشورا. راجع المنطقة الزمنية المعروضة لمساحة العمل.",
  "Open a result and review its source link, date, and available evidence. A hypothesis is a proposed test, not proof that a format will perform.":
    "افتح نتيجة وراجع رابط مصدرها وتاريخها وأدلتها المتاحة. الفرضية اختبار مقترح، لا دليل على أن الصيغة ستؤدي جيدا.",
