  Quote: "اقتباس",
  "Quote + attribution": "اقتباس ونسبة إلى صاحبه",
  "REELassati AI transcription": "تفريغ REELassati بالذكاء الاصطناعي",
  "REELassati AI-generated audio": "صوت REELassati مولد بالذكاء الاصطناعي",
  "REELassati Support": "دعم REELassati",
  "REELassati accessibility": "إمكانية الوصول في REELassati",
  "REELassati combines manual production tools with reviewable AI assistance. This page identifies where AI is used, the information sent when you invoke it, and the controls that remain with you.":
    "يجمع REELassati أدوات الإنتاج اليدوي ومساعدة ذكاء اصطناعي قابلة للمراجعة. تحدد هذه الصفحة مواضع استخدام الذكاء الاصطناعي والمعلومات المرسلة عند استدعائه وعناصر التحكم التي تبقى لك.",
  "REELassati credits": "رصيد REELassati",
  "REELassati designs interfaces around WCAG 2.2 AA principles: semantic structure, accessible names, visible focus, contrast, keyboard navigation, reduced motion, and feedback that does not rely on colour alone. This is an operating target, not a claim of complete certified conformance.":
    "يصمم REELassati الواجهات حول مبادئ WCAG 2.2 AA: البنية الدلالية والأسماء الميسرة والتركيز المرئي والتباين والتنقل بلوحة المفاتيح والحركة المخفضة وملاحظات لا تعتمد على اللون وحده. هذا هدف تشغيلي، وليس ادعاء بمطابقة كاملة معتمدة.",
  "REELassati home": "رئيسية REELassati",
  "REELassati is intended for human-directed creative and marketing production. It is not designed to make consequential decisions about people, infer sensitive traits, or present deceptive synthetic media as authentic.":
    "يقصد REELassati للإنتاج الإبداعي والتسويقي بتوجيه بشري. لا يصمم لاتخاذ قرارات مؤثرة تخص الأشخاص أو استنتاج سمات حساسة أو تقديم وسائط اصطناعية مضللة على أنها أصلية.",
  "REELassati is intended for users aged 18 or older. Material changes to this notice will be communicated appropriately before they take effect.":
    "يقصد REELassati للمستخدمين بعمر 18 عاما أو أكثر. يبلغ عن التغييرات الجوهرية لهذا الإشعار بصورة مناسبة قبل سريانها.",
  "REELassati provides tools to plan, create, edit, analyse, organise, and publish short-form content. You must be at least 18 and able to enter a contract. Anyone using the service for an organisation confirms authority to bind it.":
    "يوفر REELassati أدوات لتخطيط المحتوى القصير وإنشائه ومونتاجه وتحليله وتنظيمه ونشره. يجب ألا يقل عمرك عن 18 وأن تكون قادرا على التعاقد. يؤكد من يستخدم الخدمة لحساب منظمة صلاحيته لإلزامها.",
  "REELassati updates this feed internally; no action or credits are required from you.":
    "يحدث REELassati هذه الخلاصة داخليا؛ لا يلزمك إجراء أو رصيد.",
