  "Tax identifier": "المعرف الضريبي",
  "Tell Reel the result you want, such as “Add captions and a title for the first three seconds.” Use + or drop a reference into the chat for context. You can name a time range in your request.":
    "أخبر Reel بالنتيجة المطلوبة، مثل «أضف ترجمة وعنوانا لأول ثلاث ثوان». استخدم + أو أفلت مرجعا في المحادثة للسياق. يمكنك تسمية نطاق زمني في طلبك.",
  "Tell Reel what you want to change. Attach a reference, point to a moment, or start with an idea.":
    "أخبر Reel بما تريد تغييره. أرفق مرجعا أو أشر إلى لحظة أو ابدأ بفكرة.",
  "Tell the support assistant what you are trying to do, which page you used, and the exact error. It can answer product questions and help prepare the next step.":
    "أخبر مساعد الدعم بما تحاول فعله والصفحة المستخدمة والخطأ الدقيق. يمكنه الإجابة عن أسئلة المنتج والمساعدة في تجهيز الخطوة التالية.",
  "Ten real presets turn your subject into more precise video direction: camera, light, movement, audio, continuity, and exclusions. No preset guarantees performance.":
    "تحول عشرة إعدادات جاهزة حقيقية موضوعك إلى توجيه فيديو أدق: الكاميرا والضوء والحركة والصوت والاستمرارية والاستثناءات. لا يضمن أي إعداد الأداء.",
