  "Use a transparent PNG or WebP for a logo without a background.":
    "استخدم PNG أو WebP شفافا لشعار دون خلفية.",
  "Use an available sign-in provider or complete the name, email, and password fields. Use an email address you can access.":
    "استخدم مزود دخول متاحا أو أكمل الاسم والبريد وكلمة المرور. استخدم بريدا يمكنك الوصول إليه.",
  "Use as starting point": "استخدام كنقطة بداية",
  "Use at least 8 characters. Your new password replaces the old one immediately.":
    "استخدم 8 أحرف على الأقل. تستبدل كلمة المرور الجديدة القديمة فورا.",
