  "Uses existing media and measured speech. No AI credits. Apply creates one saved revision; Undo restores the previous edit.":
    "يستخدم الوسائط الموجودة وتوقيت الكلام المقاس. لا يستهلك رصيد الذكاء الاصطناعي. ينشئ تطبيق التغييرات نسخة منقحة محفوظة واحدة؛ ويستعيد التراجع المونتاج السابق.",
  "Uses measured word timings from transcription. Imported subtitles or edited lines without word timings display the whole phrase.":
    "يستخدم توقيت الكلمات المقاس من التفريغ. تعرض الترجمة المستوردة أو الأسطر المعدلة دون توقيت كلمات العبارة كاملة.",
  "Uses unused footage around the cut. Speech timing and total edit length stay fixed. Other overlapping video layers must be resolved first.":
    "يستخدم اللقطات غير المستخدمة حول القص. يبقى توقيت الكلام وطول المونتاج الإجمالي ثابتين. يجب حل طبقات الفيديو المتداخلة الأخرى أولا.",
